-- Five principles use five intentionally distinct but restrained visual panels.
UPDATE pages SET body_html='<div class="eyebrow">05 NGUYÊN TẮC HOẠT ĐỘNG</div><h1>Những nguyên tắc Sky First Network cam kết theo đuổi</h1><p class="lead">Mọi chương trình, quan hệ hợp tác và hoạt động công khai đều cần phù hợp với năm nguyên tắc dưới đây.</p><div class="principles"><div><span>01</span><h3>Tự nguyện</h3><p>Thành viên tham gia trên tinh thần tự nguyện, phù hợp khả năng và điều kiện cá nhân.</p></div><div><span>02</span><h3>Phi lợi nhuận</h3><p>Hoạt động hướng đến giáo dục và cộng đồng, không đặt mục tiêu phân chia lợi nhuận.</p></div><div><span>03</span><h3>Minh bạch</h3><p>Thông tin, hoạt động và nội dung cần công khai được thể hiện rõ ràng theo phạm vi phù hợp.</p></div><div><span>04</span><h3>Bình đẳng &amp; Tôn trọng</h3><p>Tôn trọng sự khác biệt, không phân biệt đối xử và tạo môi trường tham gia lành mạnh.</p></div><div><span>05</span><h3>Trách nhiệm cộng đồng</h3><p>Hoạt động hướng đến giá trị thực tế cho giáo dục, người học và cộng đồng.</p></div></div>'
WHERE slug='nguyen-tac' AND lang='vi';

-- Home is the entry point to real routes, rather than a static-only presentation.
UPDATE pages SET body_html='<section class="hero"><div class="container hero-grid"><div><span class="kicker">SKY FIRST NETWORK</span><h1>Giáo dục để phát triển.<br/>Kết nối để tạo giá trị.</h1><p class="lead">Mạng lưới Giáo dục &amp; Phát triển Cộng đồng Sky First kết nối người học, người trẻ, tình nguyện viên và nguồn lực xã hội để tạo nên cơ hội học tập, trải nghiệm và đóng góp có ý nghĩa.</p><div class="actions"><a class="btn primary" href="/gioi-thieu">Khám phá Sky First</a><a class="btn secondary" href="/tham-gia">Tham gia cùng Sky First</a></div></div><div class="hero-card"><img alt="Sky First Network" src="/assets/branding/sky-first-main-logo.png"/><div class="hero-note"><b>SKY FIRST NETWORK</b><span>Giáo dục · Văn hóa · Cộng đồng</span></div></div></div></section><section class="section"><div class="container"><div class="section-head"><div><div class="eyebrow">NỀN TẢNG HOẠT ĐỘNG</div><h2>Một không gian chung để học tập, trải nghiệm và đóng góp</h2></div><a class="textlink" href="/gioi-thieu">Xem giới thiệu →</a></div><div class="cards three"><a class="card linkcard" href="/gioi-thieu"><span class="mini">01 · Tổng quan</span><h3>Sky First Network là gì?</h3><p>Định danh, câu chuyện hình thành và ý nghĩa của Mạng lưới.</p></a><a class="card linkcard" href="/tam-nhin-su-menh"><span class="mini">02 · Định hướng</span><h3>Tầm nhìn &amp; Sứ mệnh</h3><p>Định hướng phát triển giáo dục, văn hóa và cộng đồng.</p></a><a class="card linkcard" href="/nguyen-tac"><span class="mini">03 · Cam kết</span><h3>Năm nguyên tắc hoạt động</h3><p>Tự nguyện, phi lợi nhuận, minh bạch, tôn trọng và trách nhiệm cộng đồng.</p></a></div></div></section><section class="section tint"><div class="container"><div class="section-head"><div><div class="eyebrow">LĨNH VỰC HOẠT ĐỘNG</div><h2>Năm trụ cột kết nối với nhau</h2></div><a class="textlink" href="/linh-vuc">Xem lĩnh vực →</a></div><div class="cards five"><a class="card linkcard" href="/linh-vuc"><span class="mini">01</span><h3>Giáo dục</h3><p>Lớp học, học liệu, học thuật và hỗ trợ người học.</p></a><a class="card linkcard" href="/linh-vuc"><span class="mini">02</span><h3>Phát triển người trẻ</h3><p>Học qua trải nghiệm, trách nhiệm và công việc thực tế.</p></a><a class="card linkcard" href="/linh-vuc"><span class="mini">03</span><h3>Tình nguyện &amp; Cộng đồng</h3><p>Kết nối năng lực đóng góp với nhu cầu phù hợp.</p></a><a class="card linkcard" href="/hop-tac"><span class="mini">04</span><h3>Kết nối &amp; Hợp tác</h3><p>Phối hợp chuyên môn, nguồn lực và chương trình.</p></a><a class="card linkcard" href="/tin-tuc"><span class="mini">05</span><h3>Truyền thông</h3><p>Lan tỏa tri thức, cơ hội và câu chuyện hoạt động.</p></a></div></div></section><section class="section"><div class="container cta"><div><span class="eyebrow">THAM GIA &amp; XÁC THỰC</span><h2>Mỗi người có một cách đồng hành</h2><p>Chọn đúng hành trình trước khi gửi thông tin đến Sky First Network.</p></div><div class="actions"><a class="btn secondary" href="/tham-gia">Các hình thức tham gia</a><a class="btn secondary" href="/tra-cuu">Tra cứu tại Sky First Network</a></div></div></section>'
WHERE slug='' AND lang='vi';
